-- Question: Heart-failure 30-day readmission by hospital. Shape: hospital, numerator, denominator, rate. Assumption: primary HF. Concepts: multi-table joins, HAVING.
SELECT h.hospital_name,SUM(r.readmitted_within_30_days) numerator,COUNT(*) denominator,1.0*SUM(r.readmitted_within_30_days)/COUNT(*) rate FROM encounters e JOIN hospitals h ON h.hospital_id=e.hospital_id JOIN encounter_diagnoses ed ON ed.encounter_id=e.encounter_id AND ed.primary_diagnosis_flag=1 JOIN diagnoses d ON d.diagnosis_id=ed.diagnosis_id JOIN readmissions r ON r.index_encounter_id=e.encounter_id WHERE d.diagnosis_code='I50.9' GROUP BY h.hospital_id,h.hospital_name HAVING COUNT(*)>=10 ORDER BY rate DESC;
